        "Եթե հարկային մարմնին ներկայացրել եք գործունեությունը դադարեցնելու մասին հայտարարություն՝ դադարեցման և վերսկսման օրերը, ինչպես հայտարարություններում։ Եթե հայտարարության մեջ նշված օրը ներկայացնելու օրվանից շուտ է, նշեք ներկայացնելու օրը. դրանից շուտ հայտարարությունը չի գործում (Հարկային օրենսգիրք, հոդված\u{A0}125, մաս\u{A0}3)։ Բացառություն է նոր ԱՁ-ն, որը հայտարարությունը ներկայացրել է հաշվառման օրվան հաջորդող օրվա ավարտը. նրա համար դա հաշվառման օրն է։ Քանի դեռ չեք վերսկսել, երկրորդ դաշտը թողեք դատարկ։";
