    /// Строки самого документа — на языке документа. Стороны — «Исполнитель
    /// и Заказчик» в счёте и в акте, как в армянских актах на услуги; слова
    /// о приёмке и подписи акта — решение человека 2026-10-14 (печати нет:
    /// её отменил закон ՀՕ-398-Ն от 2018-10-24, ст. 1, — Гражданский кодекс,
    /// ст. 296, ч. 2). Суммы прописью нет: закон о бухучёте ՀՕ-282-Ն,
    /// ст. 12, ч. 2, п. 6, просит только «денежное выражение» (решение
