        "Մի քանի եռամսյակի վարձակալական վճարն ու տոկոսը մուտքագրեք առանձին՝ յուրաքանչյուր եռամսյակի համար. եկամուտը վերաբերում է այն եռամսյակին, որի համար հաշվեգրվել է (հոդված\u{A0}40, մաս\u{A0}2, հոդված\u{A0}109, մաս\u{A0}3)։ Սեփական ծրագրի դիմաց վճարը վիճելի դեպք է. օրենսգիրքն այն համարում է ռոյալթի (հոդված\u{A0}4, մաս\u{A0}1, կետ\u{A0}34), իսկ բարձր տեխնոլոգիաների ցանկի կոդով դրույքաչափն ավելի ցածր է։ Անձնական ավանդի տոկոսներն ու անձնական գույքի վարձակալությունն այստեղ չեն մտնում։ Շենքի, տարածքի կամ հողամասի վարձակալության դեպքում կարող է գործել եկամտի ստորին սահման՝ կադաստրային արժեքից (հոդված\u{A0}109, մաս\u{A0}1)։ Ճշտեք հաշվապահի հետ։";
